namespace LordranEnemy {
public class Note {public string match,text,source;}
public static class StatusDisplay {
 public static readonly string[] Labels={"Poison","Scarlet rot","Bleed","Death blight","Frost","Sleep","Madness"};
 public static int Amount(EnemySnapshot s,int i){if(s==null||s.Remaining==null||s.Thresholds==null||i<0||i>=s.Remaining.Length||i>=s.Thresholds.Length)return 0;int max=s.Thresholds[i],left=s.Remaining[i];return max>0&&left>=0&&left<=max?max-left:0;}
 public static int[] Active(EnemySnapshot s){return Enumerable.Range(0,7).Where(i=>Amount(s,i)>0).ToArray();}
 public static Note Find(Note[] notes,string name){return notes.FirstOrDefault(n=>name.IndexOf(n.match,StringComparison.OrdinalIgnoreCase)>=0);}
}
public class HudSettings {public int Right,Edge;public bool Positioned,Upward=true,Shading=true,Topmost=true;public int Opacity=100;}
public class Overlay:Form {
 [DllImport("user32.dll")]static extern bool ReleaseCapture();
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);
 readonly string root=AppDomain.CurrentDomain.BaseDirectory;
 Dictionary<string,string> names;EnemyReader reader=new EnemyReader();EnemySnapshot enemy,previous;
 Timer timer=new Timer{Interval=500};NotifyIcon tray;ContextMenuStrip menu;Form settings;Label status;Button trackingButton,positionButton;
 HudSettings prefs=new HudSettings();bool tracking,busy,positioning,previewMode,exiting;int generation;
 string message="Tracking paused.";Color gold=Color.FromArgb(208,177,105),cream=Color.FromArgb(233,221,191);
 string SettingsPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Lordran","EnemyObserver","settings.json");}}
 public Overlay(bool preview=false){previewMode=preview;names=new JavaScriptSerializer{MaxJsonLength=4000000}.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(root,"enemy-names.json")));FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Text="EldenSpotter";Size=new Size(370,300);if(!preview)LoadPrefs();TopMost=prefs.Topmost;Rectangle area=Screen.FromPoint(Cursor.Position).WorkingArea;if(!prefs.Positioned){prefs.Right=area.Right-24;prefs.Edge=prefs.Upward?area.Bottom-24:area.Top+24;}EnsureOnScreen();FitPanel();var nativeHandle=Handle;NativeHud.SetInteractive(Handle,false);timer.Tick+=async(o,e)=>await Poll();if(!preview){CreateTray();timer.Start();}}
 protected override CreateParams CreateParams {get{var cp=base.CreateParams;cp.ExStyle|=0x80000|0x80|0x08000000;return cp;}}
 protected override bool ShowWithoutActivation {get{return true;}}
 void LoadPrefs(){try{var saved=new JavaScriptSerializer().Deserialize<HudSettings>(File.ReadAllText(SettingsPath));if(saved!=null&&saved.Opacity>=50&&saved.Opacity<=100)prefs=saved;}catch{}}
 void SavePrefs(){if(previewMode)return;try{Directory.CreateDirectory(Path.GetDirectoryName(SettingsPath));File.WriteAllText(SettingsPath,new JavaScriptSerializer().Serialize(prefs));}catch(Exception ex){message="Settings could not be saved: "+ex.Message;UpdateStatus();}}
 void EnsureOnScreen(){if(!Screen.AllScreens.Any(s=>s.WorkingArea.Contains(new Point(prefs.Right-20,prefs.Upward?prefs.Edge-20:prefs.Edge+20)))){var a=Screen.FromPoint(Cursor.Position).WorkingArea;prefs.Right=a.Right-24;prefs.Edge=prefs.Upward?a.Bottom-24:a.Top+24;}}
 void CreateTray(){menu=new ContextMenuStrip();menu.Items.Add("Settings…",null,(o,e)=>OpenSettings());menu.Items.Add("Position overlay…",null,(o,e)=>{OpenSettings();SetPositioning(true);});menu.Items.Add("Finish positioning",null,(o,e)=>SetPositioning(false));menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Start / stop offline tracking",null,(o,e)=>SetTracking(!tracking));menu.Items.Add("Exit",null,(o,e)=>ExitApp());tray=new NotifyIcon{Text="EldenSpotter",Icon=NativeHud.TrayIcon(),ContextMenuStrip=menu,Visible=true};tray.DoubleClick+=(o,e)=>OpenSettings();}
 public void StartUi(){OpenSettings();}
 void ExitApp(){if(exiting)return;exiting=true;generation++;timer.Stop();if(tray!=null){tray.Visible=false;tray.Icon.Dispose();tray.Dispose();}if(settings!=null)settings.Close();Dispose();Application.ExitThread();}
 void SetTracking(bool enabled){generation++;enemy=null;previous=null;reader.Reset();tracking=false;if(enabled&&MessageBox.Show(settings,"Use only with Elden Ring already offline and EAC disabled. This app reads memory only; it does not disable anti-cheat or change the game. Confirm your existing offline setup before starting.","Offline enemy observer",MessageBoxButtons.OKCancel)==DialogResult.OK){tracking=true;message="Waiting for Elden Ring and a locked target…";}else message="Tracking paused.";RefreshHud();}
 async Task Poll(){if(!tracking||busy||exiting||positioning)return;busy=true;int ticket=generation;try{var snap=await Task.Run(()=>reader.Poll());if(ticket!=generation||!tracking)return;if(snap==null){enemy=null;previous=null;message="No locked target.";}else if(previous==null||previous.Handle!=snap.Handle||previous.NpcId!=snap.NpcId){previous=snap;enemy=null;message="Confirming locked target…";}else{enemy=snap;previous=snap;message="Live · "+EnemyName(snap);}}catch(Exception ex){if(ticket==generation){enemy=null;previous=null;message=ex.Message;}}finally{busy=false;if(!exiting&&!IsDisposed){if(positioning)UpdateStatus();else RefreshHud();}}}
 void UpdateStatus(){if(status!=null&&!status.IsDisposed)status.Text=message;if(trackingButton!=null&&!trackingButton.IsDisposed)trackingButton.Text=tracking?"Stop tracking":"Start offline tracking";if(positionButton!=null&&!positionButton.IsDisposed)positionButton.Text=positioning?"Done positioning":"Position overlay…";if(tray!=null)tray.Text=tracking?"EldenSpotter · "+(enemy==null?"Waiting for target":"Tracking enemy"):"EldenSpotter · Tracking paused";}
 void SetPositioning(bool enabled){positioning=enabled;NativeHud.SetInteractive(Handle,enabled);if(!enabled){prefs.Right=Right;prefs.Edge=prefs.Upward?Bottom:Top;prefs.Positioned=true;SavePrefs();}RefreshHud();}
 EnemySnapshot DisplayEnemy(){return positioning?Sample():enemy;}
 string EnemyName(EnemySnapshot snap){string name;return names.TryGetValue(snap.NpcId.ToString(),out name)?name:"Unknown enemy";}
 static EnemySnapshot Sample(){return new EnemySnapshot{Stance=30,MaxStance=80,StatusBlocked=new[]{false,false,false,true,false,false,true},BaseStatus=new[]{100,100,100,999,100,100,999},Negation=new float[]{35,35,0,35,20,-10,20,20},NpcId=33500000,Hp=1750,MaxHp=2400,Remaining=new[]{334,334,99999,99999,214,99999,99999},Thresholds=new[]{334,334,99999,99999,334,99999,99999}};}
 public static Rectangle AnchoredBounds(int right,int edge,bool upward,int height){return new Rectangle(right-370,upward?edge-height:edge,370,height);}
 int HudHeight(EnemySnapshot s){return s==null?60:82+(s.Stance.HasValue?34:0)+StatusDisplay.Active(s).Length*34+(s.Negation==null?22:85)+109+(positioning?28:0);}
 void FitPanel(){var s=DisplayEnemy();Rectangle bounds=AnchoredBounds(prefs.Right,prefs.Edge,prefs.Upward,HudHeight(s));SetBounds(bounds.X,bounds.Y,bounds.Width,bounds.Height);}
 void RefreshHud(){FitPanel();UpdateStatus();if(DisplayEnemy()==null){Hide();return;}using(var bitmap=RenderBitmap())NativeHud.Present(Handle,bitmap,Location,(byte)(prefs.Opacity*255/100));if(!Visible)Show();}
 void TextAt(Graphics g,string text,Rectangle bounds,Color color,float size,bool bold,bool serif=false){using(var font=new Font(serif?"Georgia":"Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular))using(var shadow=new SolidBrush(Color.FromArgb(235,0,0,0)))using(var brush=new SolidBrush(color))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.LineLimit}){var offset=bounds;offset.Offset(1,1);g.DrawString(text,font,shadow,offset,format);g.DrawString(text,font,brush,bounds,format);}}
 void Bar(Graphics g,int y,int w,double fraction,Color color){using(var shadow=new SolidBrush(Color.FromArgb(160,10,8,5)))g.FillRectangle(shadow,16,y,w,6);using(var brush=new SolidBrush(color))g.FillRectangle(brush,16,y,(float)(w*Math.Max(0,Math.Min(1,fraction))),6);using(var pen=new Pen(Color.FromArgb(110,208,177,105)))g.DrawRectangle(pen,16,y,w,6);}
 Bitmap SoftShade(int width,int height){var b=new Bitmap(width,height,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);var data=b.LockBits(new Rectangle(0,0,width,height),System.Drawing.Imaging.ImageLockMode.WriteOnly,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);try{var pixels=new byte[data.Stride*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){double edge=Math.Min(Math.Min(x,width-1-x)/28.0,Math.Min(y,height-1-y)/24.0);edge=Math.Max(0,Math.Min(1,edge));int alpha=(int)(115*edge*edge*(3-2*edge));int i=y*data.Stride+x*4;pixels[i]=(byte)(6*alpha/255);pixels[i+1]=(byte)(9*alpha/255);pixels[i+2]=(byte)(10*alpha/255);pixels[i+3]=(byte)alpha;}Marshal.Copy(pixels,0,data.Scan0,pixels.Length);}finally{b.UnlockBits(data);}return b;}
 Bitmap RenderBitmap(){var b=new Bitmap(Width,Height,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);g.TextRenderingHint=TextRenderingHint.AntiAliasGridFit;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;var s=DisplayEnemy();if(s==null)return b;if(prefs.Shading){using(var shade=SoftShade(Width,Height))g.DrawImageUnscaled(shade,0,0);}int w=Width-32,y=10;if(positioning){TextAt(g,"POSITION PREVIEW · DRAG ANYWHERE",new Rectangle(16,y,w,22),gold,8,true);y+=28;}
 TextAt(g,EnemyName(s),new Rectangle(16,y,w,30),cream,16,false,true);y+=34;TextAt(g,string.Format("{0:N0} / {1:N0} HP",s.Hp,s.MaxHp),new Rectangle(16,y,w,20),cream,9,false);Bar(g,y+22,w,s.Hp/(double)s.MaxHp,Color.FromArgb(181,55,40));y+=38;
 if(s.Stance.HasValue&&s.MaxStance.HasValue){double taken=s.MaxStance.Value-s.Stance.Value;TextAt(g,string.Format("Stance break    {0:0.#} / {1:0.#}",taken,s.MaxStance.Value),new Rectangle(16,y,w,20),cream,9,false);Bar(g,y+22,w,taken/s.MaxStance.Value,gold);y+=34;}
 Color[] colors={Color.FromArgb(132,160,72),Color.FromArgb(190,82,67),Color.FromArgb(193,68,67),Color.FromArgb(153,141,86),Color.FromArgb(121,187,211),Color.FromArgb(169,134,206),Color.FromArgb(218,169,49)};foreach(int i in StatusDisplay.Active(s)){int amount=StatusDisplay.Amount(s,i);TextAt(g,StatusDisplay.Labels[i]+"    "+amount+" / "+s.Thresholds[i],new Rectangle(16,y,w,20),cream,9,false);Bar(g,y+22,w,amount/(double)s.Thresholds[i],colors[i]);y+=34;}
 TextAt(g,"DAMAGE NEGATION",new Rectangle(16,y,w,18),gold,8,false);y+=21;if(s.Negation!=null){for(int i=0;i<8;i++){int x=16+(i%4)*(w/4),row=y+(i/4)*29;TextAt(g,NpcDamage.Labels[i],new Rectangle(x,row,w/4,16),cream,8,false);TextAt(g,string.Format("{0:0.#}%",s.Negation[i]),new Rectangle(x,row+13,w/4,18),s.Negation[i]<0?Color.FromArgb(154,194,130):cream,9,false);}y+=64;}else{TextAt(g,"Unavailable",new Rectangle(16,y,w,22),cream,9,false);y+=1;}
 TextAt(g,"STATUS SUSCEPTIBILITY",new Rectangle(16,y,w,18),gold,8,false);y+=21;for(int i=0;i<7;i++){int x=16+(i%2)*(w/2);string state=StatusSusceptibility.State(s,i);TextAt(g,StatusDisplay.Labels[i],new Rectangle(x,y+(i/2)*21,92,21),cream,9,false);TextAt(g,state,new Rectangle(x+92,y+(i/2)*21,w/2-92,21),state=="Yes"?Color.FromArgb(154,194,130):gold,9,false);}}
 return b;}
 protected override void OnMouseDown(MouseEventArgs e){if(positioning&&e.Button==MouseButtons.Left){ReleaseCapture();SendMessage(Handle,0xA1,new IntPtr(2),IntPtr.Zero);prefs.Right=Right;prefs.Edge=prefs.Upward?Bottom:Top;}base.OnMouseDown(e);}
 protected override void OnMove(EventArgs e){base.OnMove(e);if(positioning&&IsHandleCreated&&!previewMode){using(var b=RenderBitmap())NativeHud.Present(Handle,b,Location,(byte)(prefs.Opacity*255/100));}}
 void OpenSettings(){if(settings!=null&&!settings.IsDisposed){settings.Show();settings.Activate();return;}settings=new Form{Text="EldenSpotter settings",Size=new Size(470,620),MinimumSize=new Size(470,620),BackColor=Color.FromArgb(25,24,20),ForeColor=cream,Font=new Font("Segoe UI",10),StartPosition=FormStartPosition.CenterScreen,MaximizeBox=false};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20),AutoScroll=true};settings.Controls.Add(flow);flow.Controls.Add(new Label{Text="Enemy observer",Font=new Font("Georgia",18),AutoSize=true,Margin=new Padding(0,0,0,12)});status=new Label{Text=message,Size=new Size(405,65)};flow.Controls.Add(status);trackingButton=new Button{Text=tracking?"Stop tracking":"Start offline tracking",Size=new Size(405,32)};trackingButton.Click+=(o,e)=>SetTracking(!tracking);flow.Controls.Add(trackingButton);positionButton=new Button{Text=positioning?"Done positioning":"Position overlay…",Size=new Size(405,32)};positionButton.Click+=(o,e)=>SetPositioning(!positioning);flow.Controls.Add(positionButton);flow.Controls.Add(new Label{Text="Positioning shows sample stats. Drag the HUD, then select Done positioning. Normal HUD lets clicks pass through.",Size=new Size(405,48)});
 var upward=new CheckBox{Text="Expand upward from the bottom edge",Checked=prefs.Upward,AutoSize=true};upward.CheckedChanged+=(o,e)=>{prefs.Edge=upward.Checked?Bottom:Top;prefs.Upward=upward.Checked;SavePrefs();RefreshHud();};flow.Controls.Add(upward);var shade=new CheckBox{Text="Soft shading behind the HUD",Checked=prefs.Shading,AutoSize=true};shade.CheckedChanged+=(o,e)=>{prefs.Shading=shade.Checked;SavePrefs();RefreshHud();};flow.Controls.Add(shade);var pin=new CheckBox{Text="Always on top",Checked=prefs.Topmost,AutoSize=true};pin.CheckedChanged+=(o,e)=>{TopMost=prefs.Topmost=pin.Checked;SavePrefs();};flow.Controls.Add(pin);var opacity=new NumericUpDown{Minimum=50,Maximum=100,Value=prefs.Opacity,Width=100};flow.Controls.Add(new Label{Text="HUD opacity (%)",AutoSize=true});opacity.ValueChanged+=(o,e)=>{prefs.Opacity=(int)opacity.Value;SavePrefs();RefreshHud();};flow.Controls.Add(opacity);
 var corners=new FlowLayoutPanel{Size=new Size(410,36)};foreach(bool bottom in new[]{false,true}){bool btm=bottom;var button=new Button{Text=bottom?"Bottom-right":"Top-right",Size=new Size(195,30)};button.Click+=(o,e)=>{var area=Screen.FromPoint(Cursor.Position).WorkingArea;prefs.Upward=btm;prefs.Right=area.Right-24;prefs.Edge=btm?area.Bottom-24:area.Top+24;prefs.Positioned=true;FitPanel();upward.Checked=btm;SavePrefs();RefreshHud();};corners.Controls.Add(button);}flow.Controls.Add(corners);var details=new Button{Text="Copy diagnostics",Size=new Size(195,30)};details.Click+=(o,e)=>Clipboard.SetText(message+"\r\n"+(enemy==null?"":("NPC "+enemy.NpcId+"\r\n"+enemy.DamageError+"\r\n"+enemy.StatusError)));flow.Controls.Add(details);settings.FormClosing+=(o,e)=>{SetPositioning(false);};StyleSettings(settings);if(previewMode){settings.StartPosition=FormStartPosition.Manual;settings.Location=new Point(-12000,-12000);settings.ShowInTaskbar=false;}settings.Show();UpdateStatus();}
 void StyleSettings(Control control){foreach(Control child in control.Controls){if(child is Button){var button=(Button)child;button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=Color.FromArgb(110,93,54);button.BackColor=Color.FromArgb(45,40,29);button.ForeColor=cream;button.UseVisualStyleBackColor=false;}if(child is NumericUpDown){child.BackColor=Color.FromArgb(35,32,25);child.ForeColor=cream;}StyleSettings(child);}}
 public void Preview(){if(NativeHud.IsInteractive(Handle))throw new Exception("Normal HUD must pass clicks through.");prefs.Right=-10000;prefs.Edge=-10000;TopMost=false;enemy=Sample();FitPanel();using(var b=RenderBitmap())b.Save(Path.Combine(root,"preview.png"));prefs.Shading=false;using(var b=RenderBitmap())b.Save(Path.Combine(root,"preview-transparent.png"));prefs.Shading=true;positioning=true;FitPanel();using(var b=RenderBitmap())b.Save(Path.Combine(root,"preview-positioning.png"));positioning=false;enemy.Remaining=(int[])enemy.Thresholds.Clone();FitPanel();using(var b=RenderBitmap())b.Save(Path.Combine(root,"preview-idle.png"));for(int i=0;i<7;i++)enemy.Remaining[i]=enemy.Thresholds[i]/2;FitPanel();using(var b=RenderBitmap())b.Save(Path.Combine(root,"preview-all-statuses.png"));RefreshHud();if(!Visible)throw new Exception("Target HUD must show.");enemy=null;RefreshHud();if(Visible)throw new Exception("No-target HUD must hide.");SetPositioning(true);if(!NativeHud.IsInteractive(Handle))throw new Exception("Positioning HUD must receive drag input.");if(!Visible)throw new Exception("Position preview must show without target.");SetPositioning(false);if(NativeHud.IsInteractive(Handle))throw new Exception("Finished HUD must pass clicks through.");if(Visible)throw new Exception("Finished placement must hide without target.");var up=AnchoredBounds(1920,1056,true,450);var down=AnchoredBounds(1920,24,false,450);if(up.Bottom!=1056||up.Right!=1920||down.Top!=24||down.Right!=1920)throw new Exception("HUD anchor regression.");OpenSettings();Application.DoEvents();using(var screenshot=new Bitmap(settings.Width,settings.Height)){settings.DrawToBitmap(screenshot,settings.ClientRectangle);screenshot.Save(Path.Combine(root,"preview-settings.png"));}settings.Close();File.WriteAllText(Path.Combine(root,"layout-test-results.txt"),"PASS: click-through normal/placement transitions, real HUD shows for a target, hides without a target, placement shows sample HUD, finishing placement hides it, top/bottom/right anchors preserved. Rendered simulated HUD only.");Dispose();}
 [STAThread]public static void Main(string[] args){if(args.Contains("--self-test")){try{Tests.Run();}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),e.ToString());Environment.Exit(1);}return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool preview=args.Contains("--preview");var app=new Overlay(preview);if(preview){app.Preview();return;}app.StartUi();Application.Run();}
